const input=$json??{};
const event=String(input.provider_event??input.delivery_status??input.status??'').toLowerCase();
const sellerResponse=String(input.seller_response??input.inbound_message??input.message??'').trim();
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
