let status='pending'; let nextWorkflow='WF-341'; let route='awaiting_receipt'; let classification='no_response'; let counterofferAmount=null; let reason='Awaiting provider receipt or seller response.';
if(hardBlock){status=dnc?'dnc_blocked':'blocked';route='blocked';nextWorkflow='WF-126';reason=dnc?'Seller is on DNC; inbound/outbound action requires blocking.' :'Active blocker prevents communication processing.';}
else if(!identityComplete||!dispatchId||!idempotencyKey){status='incomplete';route='incomplete';nextWorkflow='WF-341';reason='Missing deal identity or dispatch idempotency evidence.';}
else if(['delivered','sent','accepted'].includes(event)&&!sellerResponse){status='delivered_awaiting_response';route='awaiting_seller_response';nextWorkflow='WF-343';reason='Provider confirms delivery; awaiting seller response.';}
else if(['failed','bounced','rejected','undelivered'].includes(event)){status='delivery_failed';route='retry_or_review';nextWorkflow='WF-341';reason='Provider reports delivery failure; retry/review is required.';}
else if(sellerResponse){
 const normalized=sellerResponse.toLowerCase();
 const nums=sellerResponse.replace(/[$,]/g,'').match(/\b\d+(?:\.\d+)?\b/g)||[];
 const parsed=nums.map(Number).filter(Number.isFinite); counterofferAmount=parsed.length?Math.max(...parsed):null;
 if(/\b(don't|do not)\s*(contact|call|text|message)|stop\s*(contacting|texting|calling)|remove me|unsubscribe/.test(normalized)){classification='dnc';status='dnc_received';route='dnc';nextWorkflow='WF-126';reason='Seller requested no further contact.';}
 else if(/\b(yes|accept|accepted|deal|let's do it|sounds good|agreed)\b/.test(normalized)){classification='accepted';status='response_received';route='accepted';nextWorkflow='WF-344';reason='Seller response indicates acceptance; negotiation/contract decision required.';}
 else if(counterofferAmount!==null&&(/\$|offer|take|would you|can you|price|counter|need/.test(normalized))){classification='counteroffer';status='response_received';route='counteroffer';nextWorkflow='WF-344';reason='Seller response contains a likely price/counteroffer signal.';}
 else if(/\b(no|not interested|pass|decline|declined|too low|can't|cannot)\b/.test(normalized)){classification='rejected';status='response_received';route='rejected';nextWorkflow='WF-345';reason='Seller response indicates rejection or unwillingness.';}
 else if(/\?|what|why|how|when|where|explain|tell me/.test(normalized)){classification='question';status='response_received';route='question';nextWorkflow='WF-344';reason='Seller response requires clarification or negotiation handling.';}
 else {classification='other_response';status='response_received';route='other';nextWorkflow='WF-344';reason='Seller response received but requires AI negotiation classification.';}
}
const activity={activity_type:'delivery_receipt_seller_response_ai_classification',subject:'WF-342 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,event,classification,route,next_workflow:nextWorkflow,dispatch_id:dispatchId,idempotency_key:idempotencyKey,counteroffer_amount:counterofferAmount,dynamic_mao:dynamicMao,dnc,blockers,reason};
